<script lang="ts">
  import{onDestroy}from'svelte';import Modal from'./Modal.svelte';import{api}from'../lib/api';import{buildModelTestPayload,DEFAULT_MODEL_TEST_TIMEOUT_MS,pollModelTest,rawResponseText,responseText,safeUsageRows}from'../lib/model-test';import{t}from'../../shared/i18n.svelte';
  let{model}:{model:string}=$props();let running=$state(false);let modalOpen=$state(false);let taskId=$state('');let result=$state<unknown>(null);let status=$state('');let error=$state('');let controller:AbortController|null=null;let usage=$derived(safeUsageRows(result&&typeof result==='object'?(result as Record<string,unknown>).usage:null));
  async function run():Promise<void>{if(running)return;modalOpen=true;running=true;result=null;status=t('modelTest.starting');error='';controller=new AbortController();const timeout=window.setTimeout(()=>controller?.abort(),DEFAULT_MODEL_TEST_TIMEOUT_MS);try{const started=await api.post<{task_id:string}>('/admin/api/test',{endpoint:'/v1/responses',payload:buildModelTestPayload(model)},controller.signal);taskId=started.task_id;status=t('modelTest.waiting');const completed=await pollModelTest(taskId,controller.signal);taskId='';if(completed.status==='error')throw new Error(completed.error??t('modelTest.failed'));if(completed.status==='cancelled')throw new DOMException(t('modelTest.cancelled'),'AbortError');result=completed.body;status=t('modelTest.completed',{status:completed.status_code??200});}catch(cause){if(taskId){const current=taskId;taskId='';await api.del(`/admin/api/test/${encodeURIComponent(current)}`).catch(()=>undefined);}if(cause instanceof DOMException&&cause.name==='AbortError')status=t('modelTest.cancelled');else if(cause instanceof DOMException&&cause.name==='TimeoutError')status=t('modelTest.timedOut');else error=cause instanceof Error?cause.message:String(cause);}finally{window.clearTimeout(timeout);running=false;controller=null;}}
  async function cancel():Promise<void>{controller?.abort();const current=taskId;taskId='';if(current)await api.del(`/admin/api/test/${encodeURIComponent(current)}`).catch(()=>undefined);}function close():void{if(running)void cancel();modalOpen=false;}onDestroy(()=>{void cancel();});
</script>
<button class="btn btn-sm btn-test" disabled={running} onclick={()=>void run()}>{t('btn.test')}</button>
<Modal open={modalOpen} labelledby={`test-title-${model}`} wide onclose={close}>{#snippet header()}<h3 id={`test-title-${model}`}>{t('modelTest.title',{model})}</h3>{/snippet}<div class="test-meta">{#if status}<span class="meta-item" role="status"><strong>{t('modelTest.status')}</strong> {status}</span>{/if}</div>{#if error}<div class="test-output" role="alert">{error}</div>{/if}{#if result!==null}<div class="test-output">{responseText(result)}</div>{/if}{#if usage.length}<div class="test-meta">{#each usage as [label,value]}<span class="meta-item"><strong>{label}:</strong> {value}</span>{/each}</div>{/if}<details class="test-details"><summary>{t('modelTest.rawResponse')}</summary><div class="detail-body"><pre>{rawResponseText(result)}</pre></div></details>{#snippet actions()}{#if running}<button class="btn btn-danger" onclick={()=>void cancel()}>{t('btn.cancel')}</button>{/if}<button class="btn" onclick={close}>{t('btn.close')}</button>{/snippet}</Modal>
